package com.nutritionplatform.progress.service;
import com.nutritionplatform.progress.dto.ProgressRequests; import org.springframework.jdbc.core.simple.JdbcClient; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDate; import java.util.UUID;
@Service public class ProgressService { private final JdbcClient db; public ProgressService(JdbcClient db){this.db=db;} @Transactional public void checkin(UUID u,ProgressRequests.Checkin r){db.sql("INSERT INTO daily_checkin(id,user_id,checkin_date,hunger_level,energy_level,sleep_quality,mood,water_ml,exercise_minutes,meal_plan_adherence,notes) VALUES(:id,:u,:d,:h,:e,:s,:m,:w,:x,:a,:n) ON CONFLICT(user_id,checkin_date) DO UPDATE SET hunger_level=:h,energy_level=:e,sleep_quality=:s,mood=:m,water_ml=:w,exercise_minutes=:x,meal_plan_adherence=:a,notes=:n").param("id",UUID.randomUUID()).param("u",u).param("d",LocalDate.now()).param("h",r.hungerLevel()).param("e",r.energyLevel()).param("s",r.sleepQuality()).param("m",r.mood()).param("w",r.waterMl()).param("x",r.exerciseMinutes()).param("a",r.mealPlanAdherence()).param("n",r.notes()).update();} public void weight(UUID u,ProgressRequests.Weight r){db.sql("INSERT INTO weight_record(id,user_id,weight_kg,recorded_at) VALUES(:id,:u,:w,:d)").param("id",UUID.randomUUID()).param("u",u).param("w",r.weightKg()).param("d",r.recordedAt()==null?LocalDate.now():r.recordedAt()).update();} public void measurement(UUID u,ProgressRequests.Measurement r){db.sql("INSERT INTO body_measurement(id,user_id,measurement_type,value_cm,recorded_at) VALUES(:id,:u,:t,:v,:d)").param("id",UUID.randomUUID()).param("u",u).param("t",r.measurementType()).param("v",r.valueCm()).param("d",r.recordedAt()==null?LocalDate.now():r.recordedAt()).update();} public java.util.List<java.util.Map<String,Object>> weights(UUID u){return db.sql("SELECT recorded_at,weight_kg FROM weight_record WHERE user_id=:u ORDER BY recorded_at ASC LIMIT 30").param("u",u).query((rs,row)->java.util.Map.<String,Object>of("date",rs.getObject(1).toString(),"weightKg",rs.getBigDecimal(2))).list();} }
